function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'green';

  // tree trunk
  ctx.beginPath();
  ctx.rect(W/2 - 10, H - 100, 20, 100);
  ctx.fill();
  ctx.stroke();

  // tree top
  ctx.beginPath();
  ctx.arc(W/2, H - 150, 50, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // broccoli florets
  for (let i = 0; i < 10; i++) {
    ctx.beginPath();
    ctx.arc(W/2 + Math.cos(i + t) * 30, H - 150 + Math.sin(i + t) * 30, 10, 0, 2 * Math.PI);
    ctx.fill();
    ctx.stroke();
  }

  // cancer cells
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.arc(W/2 + Math.cos(i + t * 2) * 80, H - 150 + Math.sin(i + t * 2) * 80, 5, 0, 2 * Math.PI);
    ctx.fillStyle = 'red';
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = 'green';
  }

  // stick figure
  ctx.beginPath();
  ctx.arc(W/2, H - 50, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H - 30);
  ctx.lineTo(W/2, H - 10);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H - 20);
  ctx.lineTo(W/2 - 20, H);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H - 20);
  ctx.lineTo(W/2 + 20, H);
  ctx.stroke();

  ctx.restore();
}
